// /licenses: third-party open source notices. The data is generated by
// scripts/generate-licenses.mjs (pnpm licenses:generate) from the production
// dependency closure and public/fonts, and committed, so this page needs no
// build step. License texts are reproduced verbatim, as their terms require.

import { useMemo, useState } from 'react';

import { ExternalLink, LegalDocument, LegalSection } from '@/components/legal/LegalDocument';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { BRAND_NAME, LAST_UPDATED } from '@/lib/legal';
import notices from '@/components/legal/third-party-licenses.json';

const DATA = notices;
type PackageNotice = (typeof notices.packages)[number];

function LicenseText({ text }: { text: string }) {
  return (
    <pre className="mt-3 max-h-80 overflow-auto whitespace-pre-wrap break-words rounded-lg border border-border bg-muted/40 p-4 font-mono text-xs leading-relaxed text-foreground">
      {text}
    </pre>
  );
}

function PackageRow({ pkg }: { pkg: PackageNotice }) {
  return (
    <li className="py-3">
      <details className="group">
        <summary className="cursor-pointer list-none rounded-md py-1 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
          <span className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
            <span className="font-medium text-foreground">{pkg.name}</span>
            <span className="text-sm tabular-nums text-muted-foreground">{pkg.version}</span>
            <span className="text-sm text-muted-foreground">· {pkg.license}</span>
            <span className="text-sm font-medium text-primary">View notice</span>
          </span>
        </summary>
        <div className="mt-2 space-y-2 text-sm text-foreground">
          {pkg.author && <p>Author: {pkg.author}</p>}
          {pkg.repository && (
            <p>
              Source: <ExternalLink href={pkg.repository}>{pkg.repository}</ExternalLink>
            </p>
          )}
          {pkg.textRefs.length > 0 ? (
            pkg.textRefs.map((ref) => <LicenseText key={ref} text={DATA.texts[ref] ?? ''} />)
          ) : (
            <p className="text-muted-foreground">
              This package does not include a license file. It is published under the {pkg.license} license; see
              its source repository for the full terms.
            </p>
          )}
        </div>
      </details>
    </li>
  );
}

export default function Licenses() {
  const [query, setQuery] = useState('');
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return DATA.packages;
    return DATA.packages.filter(
      (p) => p.name.toLowerCase().includes(q) || p.license.toLowerCase().includes(q),
    );
  }, [query]);

  return (
    <LegalDocument
      eyebrow="Legal"
      title="Open source licenses"
      lastUpdated={LAST_UPDATED}
      lede={
        <p>
          {BRAND_NAME} is built with open source software and fonts. We are grateful to their authors. The notices
          below are reproduced as their licenses require.
        </p>
      }
    >
      <LegalSection id="fonts" title="Fonts">
        <ul className="divide-y divide-border">
          {DATA.fonts.map((font) => (
            <li key={font.name} className="py-3">
              <details>
                <summary className="cursor-pointer list-none rounded-md py-1 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
                  <span className="flex flex-wrap items-baseline gap-x-3 gap-y-1">
                    <span className="font-medium text-foreground">{font.name}</span>
                    <span className="text-sm text-muted-foreground">· SIL Open Font License 1.1</span>
                    <span className="text-sm font-medium text-primary">View notice</span>
                  </span>
                </summary>
                <div className="mt-2 space-y-2 text-sm text-foreground">
                  <p>{font.copyright}</p>
                  <p>
                    Source: <ExternalLink href={font.url}>{font.url}</ExternalLink>
                  </p>
                  <LicenseText text={font.text} />
                </div>
              </details>
            </li>
          ))}
        </ul>
      </LegalSection>

      <LegalSection id="packages" title={`Software packages (${DATA.packages.length})`}>
        <div className="space-y-2">
          <Label htmlFor="license-filter">Filter by package or license</Label>
          <Input
            id="license-filter"
            type="search"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="For example: react or MIT"
            autoComplete="off"
            className="h-11 max-w-md"
          />
          <p className="text-sm text-muted-foreground" aria-live="polite">
            Showing {filtered.length} of {DATA.packages.length} packages.
          </p>
        </div>
        <ul className="divide-y divide-border">
          {filtered.map((pkg) => (
            <PackageRow key={`${pkg.name}@${pkg.version}`} pkg={pkg} />
          ))}
        </ul>
      </LegalSection>
    </LegalDocument>
  );
}
